// Flatten GoCardless -> flat rows ready for upsert.
const acct = $('Loop Accounts').item.json;
const resp = $('Fetch Transactions').first().json;
const booked = resp?.transactions?.booked ?? [];

// balance: prefer interimAvailable, else first entry
const bals = $('Fetch Balance').first().json?.balances ?? [];
const pick = bals.find(b => b.balanceType === 'interimAvailable') || bals[0];
const balance = pick ? parseFloat(pick.balanceAmount.amount) : null;

const rows = booked.map(t => {
  const amount = parseFloat(t.transactionAmount.amount);
  const cp = t.creditorName || t.debtorName || '';
  const descr = t.remittanceInformationUnstructured
    || (Array.isArray(t.remittanceInformationUnstructuredArray)
        ? t.remittanceInformationUnstructuredArray.join(' ') : '')
    || '';
  // own-account transfers must not count as spend
  const hay = (cp + ' ' + descr).toLowerCase();
  const isInternal = /savings|santaupos|own transfer|vidinis|between accounts/.test(hay);
  return {
    id: t.transactionId || t.internalTransactionId
        || `${acct.id}-${t.bookingDate}-${t.transactionAmount.amount}`,
    account_id: acct.id,
    booked_on: t.bookingDate || t.valueDate,
    amount,
    currency: t.transactionAmount.currency || 'EUR',
    counterparty: cp.slice(0, 200),
    description: descr.slice(0, 500),
    is_internal: isInternal,
    raw: JSON.stringify(t),
    _balance: balance
  };
});

if (!rows.length) return [{ json: { _empty: true, account_id: acct.id, _balance: balance } }];
return rows.map(json => ({ json }));

