// Parse Ollama's JSON, clamp to the known category set.
const VALID = ['Housing','Food','Transport','Utilities','Subscriptions','Health','Leisure','Kid','Other','Income'];
const out = [];
for (const item of $input.all()) {
  const txn = $('Ollama Classify').all().indexOf(item) >= 0 ? item : item;
  let cat = 'Other', conf = 0;
  try {
    const parsed = JSON.parse(item.json.response ?? '{}');
    if (VALID.includes(parsed.category)) { cat = parsed.category; conf = Number(parsed.confidence) || 0.5; }
  } catch (e) { /* fall through to Other */ }
  out.push({ json: { txn_id: item.json._txn_id ?? null, category: cat, confidence: Math.min(1, Math.max(0, conf)) } });
}
return out;
